+#[test]
+fn a_stated_holder_wins_over_the_default() {
+    let (world, mut history) = mounted(Some("tormach-770mx"));
+    assert_eq!(add(&world, &mut history, HolderPick::Named("bt40 er20".into())).as_deref(), Some("BT40 ER20"));
+    let (world, mut history) = mounted(Some("tormach-770mx"));
